public final class WebhookService { private final EventLog events; private final FulfillmentRepo fulfillments; private final InventoryClient inventory; private final FailureInjector failure; public WebhookService(EventLog e,FulfillmentRepo f,InventoryClient i,FailureInjector x){events=e;fulfillments=f;inventory=i;failure=x;} public void paid(String eventId,String orderId){ if(!events.record(eventId))return; Fulfillment f=fulfillments.getOrCreate(eventId,orderId); if(f.completed)return; String key=inventory.reserve(orderId,"event:"+eventId); failure.afterReserve(orderId); f.reservationKey=key; f.completed=true; } }
